def assign_grade(score: float, attendance: float, late_days: int, extra_credit: bool, retake: bool) -> str:
    GRADE_THRESHOLDS = [
        (90, "A"),
        (80, "B"),
        (70, "C"),
        (60, "D"),
    ]

    GRADE_ORDER = ["A", "B", "C", "D", "F"]

    def lower_grade(grade: str, steps: int = 1) -> str:
        idx = GRADE_ORDER.index(grade)
        return GRADE_ORDER[min(idx + steps, len(GRADE_ORDER) - 1)]

    def higher_grade(grade: str, steps: int = 1) -> str:
        idx = GRADE_ORDER.index(grade)
        return GRADE_ORDER[max(idx - steps, 0)]

    grade = next((g for threshold, g in GRADE_THRESHOLDS if score >= threshold), "F")

    if attendance < 0.75:
        if grade in ("A", "B"):
            grade = "C"
        elif grade == "C":
            grade = lower_grade(grade)

    if late_days > 5 and grade != "F":
        grade = lower_grade(grade, steps=GRADE_ORDER.index(grade) - GRADE_ORDER.index("D"))

    if extra_credit and grade != "A":
        grade = higher_grade(grade)

    if retake and grade == "F":
        grade = "D"

    return grade
