from dataclasses import dataclass
from enum import Enum
from typing import Optional


class Country(str, Enum):
    US = "US"
    CA = "CA"
    UK = "UK"
    DE = "DE"
    FR = "FR"


BASE_COST_BY_COUNTRY: dict[str, float] = {
    Country.US: 5.0,
    Country.CA: 8.0,
    Country.UK: 12.0,
    Country.DE: 12.0,
    Country.FR: 12.0,
}
DEFAULT_BASE_COST = 20.0

WEIGHT_SURCHARGES: list[tuple[float, float]] = [
    (10.0, 10.0),
    (5.0, 5.0),
]

EXPRESS_MULTIPLIER = 1.5
MEMBER_DISCOUNT = 0.9
FREE_SHIPPING_COUPON = "FREESHIP"
FREE_SHIPPING_THRESHOLD = 15.0


@dataclass(frozen=True)
class ShippingRequest:
    weight: float
    country: str
    express: bool
    is_member: bool
    coupon: Optional[str] = None

    def __post_init__(self) -> None:
        if self.weight < 0:
            raise ValueError(f"Weight must be non-negative, got {self.weight}.")
        if not self.country:
            raise ValueError("Country must not be empty.")


def _base_cost(country: str) -> float:
    return BASE_COST_BY_COUNTRY.get(country, DEFAULT_BASE_COST)


def _weight_surcharge(weight: float) -> float:
    for threshold, surcharge in WEIGHT_SURCHARGES:
        if weight > threshold:
            return surcharge
    return 0.0


def _apply_express(cost: float, express: bool) -> float:
    return cost * EXPRESS_MULTIPLIER if express else cost


def _apply_member_discount(cost: float, is_member: bool) -> float:
    return cost * MEMBER_DISCOUNT if is_member else cost


def _apply_coupon(cost: float, coupon: Optional[str]) -> float:
    if coupon == FREE_SHIPPING_COUPON and cost < FREE_SHIPPING_THRESHOLD:
        return 0.0
    return cost


def shipping_cost(request: ShippingRequest) -> float:
    """Calculate the shipping cost for a given request.

    Args:
        request: A ShippingRequest dataclass containing all shipping parameters.

    Returns:
        The final shipping cost as a float.
    """
    cost = _base_cost(request.country)
    cost += _weight_surcharge(request.weight)
    cost = _apply_express(cost, request.express)
    cost = _apply_member_discount(cost, request.is_member)
    cost = _apply_coupon(cost, request.coupon)
    return round(cost, 2)

