import re
import unicodedata

COMMON_PASSWORDS = frozenset({
    "password", "123456", "qwerty", "abc123", "letmein",
    "monkey", "1234567890", "password1", "iloveyou", "admin",
    "welcome", "login", "passw0rd", "master", "hello",
})

SPECIAL_CHARACTERS = frozenset("!@#$%^&*()_+-=[]{}|;':\",./<>?`~\\")


def password_strength(pw: str) -> str:
    """
    Evaluate the strength of a password.

    Args:
        pw: The password string to evaluate.

    Returns:
        A string: 'very strong', 'strong', 'medium', or 'weak'.

    Raises:
        TypeError: If pw is not a string.
        ValueError: If pw is empty.
    """
    if not isinstance(pw, str):
        raise TypeError(f"Password must be a string, got {type(pw).__name__}")
    if not pw:
        raise ValueError("Password must not be empty")

    # Immediately reject common passwords
    if pw.lower() in COMMON_PASSWORDS:
        return "weak"

    score = 0
    feedback = []

    # Length checks
    if len(pw) >= 8:
        score += 1
    else:
        feedback.append("at least 8 characters")

    if len(pw) >= 12:
        score += 1

    if len(pw) >= 16:
        score += 1

    # Character variety checks
    if any(c.isupper() for c in pw):
        score += 1
    else:
        feedback.append("uppercase letters")

    if any(c.islower() for c in pw):
        score += 1
    else:
        feedback.append("lowercase letters")

    if any(c.isdigit() for c in pw):
        score += 1
    else:
        feedback.append("digits")

    if any(c in SPECIAL_CHARACTERS for c in pw):
        score += 1
    else:
        feedback.append("special characters")

    # Penalize repetitive or sequential patterns
    if _has_repetitive_patterns(pw):
        score = max(0, score - 2)

    if _has_sequential_patterns(pw):
        score = max(0, score - 1)

    # Classify by score
    if score >= 7:
        return "very strong"
    elif score >= 5:
        return "strong"
    elif score >= 3:
        return "medium"
    else:
        return "weak"


def _has_repetitive_patterns(pw: str) -> bool:
    """Detect repeated characters (e.g. 'aaaa') or repeated substrings."""
    # Three or more identical consecutive characters
    if re.search(r'(.)\1{2,}', pw):
        return True
    # Repeated substring of length >= 2 (e.g. 'abab')
    if re.search(r'(.{2,})\1', pw):
        return True
    return False


def _has_sequential_patterns(pw: str) -> bool:
    """Detect sequential character runs (e.g. 'abcd', '1234', 'dcba')."""
    SEQUENCE_LENGTH = 4
    pw_lower = pw.lower()
    for i in range(len(pw_lower) - SEQUENCE_LENGTH + 1):
        chunk = pw_lower[i:i + SEQUENCE_LENGTH]
        code_points = [ord(c) for c in chunk]
        diffs = [code_points[j + 1] - code_points[j] for j in range(len(code_points) - 1)]
        # Ascending or descending sequential run
        if all(d == 1 for d in diffs) or all(d == -1 for d in diffs):
            return True
    return False
