def ticket_price(age, student, weekday, member, group_size):
    if age < 5:
        return 0.0

    price = get_base_price(age)
    price = apply_discounts(price, student, weekday, member, group_size)

    return max(price, 0.0)


def get_base_price(age):
    if age < 18:
        return 10.0
    elif age >= 65:
        return 12.0
    else:
        return 20.0


def apply_discounts(price, student, weekday, member, group_size):
    if student:
        price *= 0.8
    if weekday:
        price *= 0.9
    if member:
        price -= 2.0
    if group_size >= 10:
        price *= 0.85
