def ticket_price(
    age: int,
    student: bool,
    weekday: bool,
    member: bool,
    group_size: int
) -> float:
    """
    Calculate the ticket price based on various discount factors.

    Args:
        age: Age of the ticket holder.
        student: Whether the ticket holder is a student.
        weekday: Whether the ticket is for a weekday.
        member: Whether the ticket holder is a member.
        group_size: Number of people in the group.

    Returns:
        The final ticket price after all applicable discounts.
    """
    if age < 0:
        raise ValueError(f"Age cannot be negative, got {age}")
    if group_size < 1:
        raise ValueError(f"Group size must be at least 1, got {group_size}")

    BASE_PRICES = {
        "child": 10.0,   # age 5–17
        "adult": 20.0,   # age 18–64
        "senior": 12.0,  # age 65+
    }

    DISCOUNTS = {
        "student": 0.80,
        "weekday": 0.90,
        "group":   0.85,
    }

    MEMBER_REDUCTION = 2.0
    GROUP_THRESHOLD = 10
    FREE_AGE_LIMIT = 5

    if age < FREE_AGE_LIMIT:
        return 0.0

    if age < 18:
        price = BASE_PRICES["child"]
    elif age >= 65:
        price = BASE_PRICES["senior"]
    else:
        price = BASE_PRICES["adult"]

    if student:
        price *= DISCOUNTS["student"]
    if weekday:
        price *= DISCOUNTS["weekday"]
    if member:
        price -= MEMBER_REDUCTION
    if group_size >= GROUP_THRESHOLD:
        price *= DISCOUNTS["group"]

    return max(price, 0.0)
```

