import json
import logging
from pathlib import Path

logger = logging.getLogger(__name__)


def load_config(path: str | Path) -> dict:
    """Load a JSON configuration file.

    Args:
        path: Path to the JSON configuration file.

    Returns:
        Parsed configuration as a dictionary, or an empty dictionary
        if the file cannot be read or parsed.
    """
    path = Path(path)

    try:
        with path.open(encoding="utf-8") as f:
            config = json.load(f)
    except FileNotFoundError:
        logger.warning("Configuration file not found: %s", path)
        return {}
    except PermissionError:
        logger.error("Permission denied when reading configuration file: %s", path)
        return {}
    except json.JSONDecodeError as exc:
        logger.error("Invalid JSON in configuration file %s: %s", path, exc)
        return {}
    except OSError as exc:
        logger.error("Failed to read configuration file %s: %s", path, exc)
        return {}

    if not isinstance(config, dict):
        logger.error(
            "Configuration file %s must contain a JSON object, got %s",
            path,
            type(config).__name__,
        )
        return {}

    return config
